      "sources": [
        {"quote": "请 PM 组织测试环境连通性检查", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "主链路通过或备用链路通过时即可结束", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "x5",
      "verdict": "SUPPORT",
      "reason": "REFERENCE_SET 将“两者”解析为紧邻前文的主链路和备用链路，两端都有原文见证。",
      "sources": [
        {"quote": "主链路通过或备用链路通过时即可结束；两者", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
